{
  "name": "archive",
  "private": true,
  "type": "module",
  "packageManager": "pnpm@11.24.0",
  "scripts": {
    "test": "node --test"
  }
}
import { issues } from "./issues.js";
import { newestFirst } from "./newest-first.js";
import { formatDate } from "./format-date.js";

export const latest = (count = 3) =>
  newestFirst(issues)
    .slice(0, count)
    .map((issue) => `#${issue.number} · ${formatDate(issue.date)}`);
const months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"];

export const formatDate = (iso) => {
  const [year, month, day] = iso.split("-").map(Number);
  return `${day} ${months[month - 1]} ${year}`;
};
export const issues = [
  { number: 1, date: "2026-01-05" },
  { number: 2, date: "2026-01-12" },
  { number: 3, date: "2026-01-19" },
  { number: 4, date: "2026-01-26" },
  { number: 5, date: "2026-02-02" },
  { number: 6, date: "2026-02-09" },
  { number: 7, date: "2026-02-16" },
  { number: 8, date: "2026-02-23" },
  { number: 9, date: "2026-03-02" },
  { number: 10, date: "2026-03-09" },
  { number: 11, date: "2026-03-16" },
  { number: 12, date: "2026-03-23" },
];
export const newestFirst = (list) => [...list].sort((a, b) => b.date.localeCompare(a.date));
export const offset = (page, perPage) => page * perPage;
import { issues } from "./issues.js";
import { newestFirst } from "./newest-first.js";
import { offset } from "./offset.js";

export const perPage = 5;

export const pageOf = (page) => {
  const start = offset(page, perPage);
  return newestFirst(issues)
    .slice(start, start + perPage)
    .map((issue) => issue.number);
};
import { test } from "node:test";
import assert from "node:assert/strict";
import { latest } from "../src/feed.js";

test("the feed lists the three newest issues with their dates", () => {
  assert.deepEqual(latest(), ["#12 · 23 Mar 2026", "#11 · 16 Mar 2026", "#10 · 9 Mar 2026"]);
});
import { test } from "node:test";
import assert from "node:assert/strict";
import { pageOf } from "../src/page.js";

test("page 1 is the five newest issues", () => {
  assert.deepEqual(pageOf(1), [12, 11, 10, 9, 8]);
});

test("page 3 holds the two oldest", () => {
  assert.deepEqual(pageOf(3), [2, 1]);
});

test("a page past the end is empty", () => {
  assert.deepEqual(pageOf(4), []);
});

